import{_ as a,O as s,o as i,c as n,a as r,i as o,f as d}from"./chunks/framework.fmIt2z2h.js";const h=JSON.parse('{"title":"D.31　风险、灾害、公共卫生、指挥与恢复","description":"","frontmatter":{"title":"D.31　风险、灾害、公共卫生、指挥与恢复","xkChars":763,"xkLessons":{"D.31":{"title":"D.31　风险、灾害、公共卫生、指挥与恢复","lead":"预警需要覆盖完整响应时间，恢复需要写清功能、覆盖和支持条件；指挥撤收不是全部生活已复原。","explanation":["原文定位：第5017—5032行，原站定位/theory/appendix-d/d-31#section-d-31。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“临时支持下真实恢复的功能不是假的”。危险源、暴露、脆弱性、观测、接受风险和行动分开。社会条件不抹去洪水病原，技术估计不独自决定谁承担风险；预防要比较行动伤害、比例、支持与复审，不无限扩权，也不等完全确定才准有限保护。[T-main]","复杂耦合、可靠组织实践、潜伏防线、系统约束、正常任务适应各有解释范围，不把不同理论合成万能事故原因。保留核对的临时绕行与取消核对不同，核心是保护功能和关键区别仍受检验，不仅是表格格式一致；相称替代需专业依据。[T-main]","没有事故的证据价值依赖暴露和观测。事故后确实建了流程，可以与安全净效果未知、某反馈学习分支未支持并列。不能因尚未证明净效果而删流程事实，也不能因流程存在就宣布安全完成。[T-main]","临界减速需特定动力学噪声采样分岔条件，普通波动不自动是崩溃信号。预警须到达能理解、调度且来得及起效的末端；只提前发出不够，核验触达理解调度保护起效均占用时间。[T-main]","警后无害可能是措施有效。若标签完整且目标固定，警后无事件仍可按该目标评分；行动避免多少损害则需要因果比较。不能为了防止误解而禁止一切预测评分，也不能把离线监测记录缺失填成零事件。[T-main]","感染、检测、确诊、报告与住院分母不同，信念变化、到检和健康后果不可互推。医学分类体验病程给付治疗各担证据责任，共同决定可改善知识，不自动保证长期健康。本节不提供个人诊断或治疗指令。[T-main]","应急指挥交接、协调撤收、特别权限退出、生活恢复有不同时间表。真实功能可依赖临时供电或持续支持，评价写清条件和实际覆盖人群，不能自动换成灾前所有用户；后来新冲击也不必证明先前有限结论全错。[T-main]","具体制度参照：马里兰2023年4月active assailant事件ICS指南第35页分别列指挥交接、简报清单和机构撤收。简报涵盖余留资源、后勤及文档；撤收要求交代长期影响、恢复需要和未完事项，因此组织退出与后续恢复是不同对象。[P-ICS]","指南是特定场景的安排，不是任何事件已完成恢复的事实；这里不把其全部现场步骤转作一般公众操作指令。新增可辨识点是退出时还有谁承接未完工作，而不是给撤收一词贴“已恢复”的总标签。[P-ICS]","恢复判断可同时承认局部真实和缺口。例如临时供电下某些家庭重新用电是实际功能恢复，但不证明常态供电已修好或所有灾前用户覆盖。超出证据的总声明须收窄，不需把已验证局部全部撤销。[T-main]","正文连接第六部分、§8.6、§12.6、§15.3.8和§16.13，核动态、观察目标、条件闭环及专业边界。急迫保护和长期评价各需相称任务，不能把事后完整解释当行动前永远无法满足的门槛。[T-main]","十一入口为31.01Beck等风险预防不确定性；31.02Perrow/Weick等复杂耦合与可靠组织；31.03Vaughan等偏差正常化和沉默；31.04灾害暴露脆弱性韧性；31.05预警临界减速响应时间；31.06公共卫生信任与分母；31.07医学化精神卫生决定因素；31.08调查问责集体学习分层；31.09医疗制度伦理共同决定；31.10NIMS/ICS交接与功能降级；31.11抢救修复重建及恢复边界。列名为导航，不假称相关原作全读。[T-main]"],"argumentSteps":["明确危险暴露观测和风险承担对象。","区分流程建成、学习证据与安全净效果。","把预警各段时间与截止时刻逐项比较。","保留事件标签和离线缺失，区分预测评分与避免损害。","恢复记录明确功能支持覆盖并安排退出承接。"],"distinctions":[{"leftTitle":"流程建立","leftText":"可核的新实践。","rightTitle":"安全净效果","rightText":"尚需后果证据，不能互相代证。"},{"leftTitle":"预警发出","leftText":"信息起点。","rightTitle":"保护起效","rightText":"须末端理解调度并及时执行。"},{"leftTitle":"警后无事件","leftText":"给定目标的观测标签。","rightTitle":"避免损害","rightText":"反事实因果问题，另需设计。"},{"leftTitle":"撤收","leftText":"组织资源退出。","rightTitle":"生活恢复","rightText":"功能及覆盖可另有时钟。"}],"boundaries":["原文边界：离线监测不能填成零事件。","原文反例：临时支持下功能真恢复，不因尚需支持就全属假恢复。","教学反例：发出提前10分钟却需12分钟响应，仍不够。"],"questions":["没事故一定安全了吗？","临时供电算假恢复吗？","预警提前10分钟够吗？","新流程成立但净效未知矛盾吗？"],"diagramPath":"/reading-assets/S-D-31/figures/d31-clock.png","caseLinks":[{"title":"2023年马里兰ICS指南的指挥移交与机构撤收","href":"https://aaiwg.maryland.gov/wp-content/uploads/sites/35/2021/02/AAIWG-ICS_Field_Operations_Guide-April-2023.pdf"}],"caseNotes":[{"title":"2023年马里兰ICS指南的指挥移交与机构撤收","text":"第35页列简报、余留资源后勤文档，以及撤收时长期影响、恢复需求和未完成事项移交。","sourceLabel":"Maryland Active Assailant Incident Interdisciplinary Work Group: ICS Field Operations Guide for Active Assailant Incidents","sourceUrl":"https://aaiwg.maryland.gov/wp-content/uploads/sites/35/2021/02/AAIWG-ICS_Field_Operations_Guide-April-2023.pdf","sourceLocator":"2023年4月，第2页适用范围，第35页Transfer of Command、Briefing Checklist、Agency Closeout","boundary":"限特定事件指南的制度安排，不证明任何一次灾害已生活恢复，也不替一般应急专业程序。","href":"https://aaiwg.maryland.gov/wp-content/uploads/sites/35/2021/02/AAIWG-ICS_Field_Operations_Guide-April-2023.pdf"}],"sourceRefs":[{"section":"D.31","start_line":5017,"end_line":5032,"startLine":5017,"endLine":5032}],"outputId":"section-d-31","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：提前量要覆盖整条链","text":"人工核验2分钟、触达1、理解2、调度3、保护起效4，串行总12分钟。提前10分钟不足2；提前15分钟剩3，但仍以每段按假设完成为条件。","assumptions":"人工严格串行、时长确定、无其他延迟，不是具体灾害操作阈值。","boundary":"现实可并行或受资源约束，需现场专业评估。"},{"title":"教学构造：支持条件与覆盖","text":"人工灾前100户，当前临时供电恢复60户。可以说这60户在临时支持下供电恢复、相对灾前户数覆盖60%；不能说全部恢复。若当前登记仅80户，60/80=75%是另一分母，不替代60/100。","assumptions":"人工同一服务标准且身份可核，不涉及真实灾区。","boundary":"未证明长期稳定、生活其他方面或未登记户不存在。"}],"counterexamples":[{"identity":"source_counterexample","text":"原文边界：离线监测不能填成零事件。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文反例：临时支持下功能真恢复，不因尚需支持就全属假恢复。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：发出提前10分钟却需12分钟响应，仍不够。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"没事故一定安全了吗？","answer":"需暴露和观测，缺失不能当零。","basis":"证据。"},{"question":"临时供电算假恢复吗？","answer":"已核功能可真恢复，需写支持和覆盖。","basis":"条件。"},{"question":"预警提前10分钟够吗？","answer":"依整条链时长，本人工例需12所以不够。","basis":"时序。"},{"question":"新流程成立但净效未知矛盾吗？","answer":"不矛盾，是不同层结果。","basis":"分层。"}],"figures":[{"path":"/reading-assets/S-D-31/figures/d31-clock.png","alt":"人工串行2+1+2+3+4=12，提前10不足。","caption":"教学构造。"},{"path":"/reading-assets/S-D-31/figures/d31-coverage.png","alt":"人工60户恢复，灾前100覆盖60%，当前80分母75%。","caption":"教学构造。"},{"path":"/reading-assets/S-D-31/figures/d31-handover.png","alt":"2023特定ICS指南交接与撤收要求移交未完恢复事项。","caption":"不是现场恢复成效证明。"}],"diagramBrief":"三图分预警时序、恢复覆盖与指挥交接。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未评价具体公共卫生干预或个人治疗。","未核某次事件撤收及长期恢复实际数据。"],"taskId":"S-D-31","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.31，第5017—5032行","claim_support":["风险证据预警时钟、学习、医学边界、退出恢复与十一入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-ICS","title":"Maryland Active Assailant Incident Interdisciplinary Work Group: ICS Field Operations Guide for Active Assailant Incidents","url":"https://aaiwg.maryland.gov/wp-content/uploads/sites/35/2021/02/AAIWG-ICS_Field_Operations_Guide-April-2023.pdf","source_type":"primary","version_or_date":"2023-04","locator":"2023年4月，第2页适用范围，第35页Transfer of Command、Briefing Checklist、Agency Closeout","claim_support":["指挥交接需简报资源后勤文档；撤收需移交未完成事项和长期影响或恢复需求。"],"limits":["本人读指定页，不声称通读83页；指南限active assailant事件，属于规定性安排而非某次事件生活已恢复的实证。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-31/lecture.md","sourcesPath":"/reading-assets/S-D-31/sources.json","sourceSlicePath":"/reading-assets/S-D-31/source/S-D-31.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-31/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-31.md","filePath":"theory/appendix-d/d-31.md"}'),l={name:"theory/appendix-d/d-31.md"};function c(p,e,u,m,_,f){const t=s("SectionLesson");return i(),n("div",null,[e[0]||(e[0]=r('<div class="theory-source"><h1 id="section-d-31" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.31</span><span class="xk-num__gap">　</span></span>风险、灾害、公共卫生、指挥与恢复 <a class="header-anchor" href="#section-d-31" aria-label="Permalink to &quot;D.31　风险、灾害、公共卫生、指挥与恢复 {#section-d-31}&quot;">​</a></h1><p>正文连接：§6；§8.6；§12.6；§15.3.8；§16.13。研究入口：31.01—31.11。</p><p>危险源、暴露、脆弱性、观测、接受风险与采取行动不同。社会条件不能抹去洪水强度或病原，技术估计也不能独自决定谁应承担风险。预防应比较行动自身的伤害、比例、可行支持和复审，既不因不确定而无限扩权，也不等到完全确定才允许有限保护。</p><p>复杂耦合、可靠组织实践、潜伏防线、系统约束和正常任务适应，各有解释范围。保留核对的临时绕行与取消核对不同。是否保留核对，要看保护功能与任务关键区别是否仍受检验，而非格式是否相同；相称的替代核验须有专业依据。没有事故的证据价值依赖暴露与观测。事故之后真正建立了新流程，可以与安全净效果尚未确定、某一反馈介导学习分支尚未获支持三项并列。</p><p>临界减速只在相应动力学、噪声、采样与分岔条件下讨论，不能把任何波动当作将崩溃的信号。预警必须到达可理解、可调度且来得及完成保护的终端；警后无害可能是措施有效。感染、检测、确诊、报告与住院分母不同；信念变化、实际到检与健康后果不能互推。</p><p>医学分类、体验、病程、给付与治疗选择分别承担证据责任。共同决定可以改善知识，不自动保证长期健康。应急指挥交接、协调撤收、特别权限退出与生活恢复有不同的时钟。临时支持下真实恢复的功能不是假的，后来再受冲击也不必证明先前结论全错；只有超出已有证据的恢复声明才需要相应收窄。</p><p>预警提前量须覆盖核验、触达、理解、调度和保护起效所需时间。标签完整且目标已固定时，警后无事件仍可按该目标评分；行动避免了多少损害另需因果比较，离线监测不能填成零事件。临时供电或持续支持下功能恢复可以是真实恢复，评价须保留支持条件和实际覆盖人群，不能自动换成全部灾前用户。</p><p>专题定位：31.01 风险社会、预防与不确定性：Ulrich Beck 等；31.02 正常事故、高可靠组织：Perrow、Weick 等；31.03 偏差正常化与组织沉默：Diane Vaughan 等；31.04 灾害脆弱性、暴露与韧性；31.05 预警、临界减速与响应时钟；31.06 流行病、公共卫生与社会信任；31.07 医学化、精神卫生与健康决定因素；31.08 事故调查、问责与集体学习；31.09 医疗制度、临床伦理与共同决定；31.10 NIMS、ICS、应急指挥与功能降级；31.11 抢救、修复、重建与假恢复。</p></div>',1)),o(t,{section:"D.31"}),e[1]||(e[1]=d("div",{class:"theory-source"},null,-1))])}const T=a(l,[["render",c]]);export{h as __pageData,T as default};
